query:
query Movies(
  $countryId: String!
  $category: String
  $cinemas: String
  $after: String
  $limit: Int
) {
  movies(
    countryId: $countryId
    category: $category
    cinemas: $cinemas
    after: $after
    limit: $limit
  ) {
    pageInfo {
      startCursor
      endCursor
      hasNextPage
      hasPreviousPage
    }
    totalCount
    edges {
      cursor
      node {
        id
        type
        countryId
        name
        originalName
        distributor
        rating
        ratingDescription
        position
        genre
        synopsis
        length
        releaseDate
        languages
        formats
        tags {
          name
          resource
        }
        media {
          resource
          type
          code
          sizes {
            large
            medium
            small
          }
        }
        cities
        cinemas
        categories
        experiences {
          icon
          name
        }
        availableForSale
        alerts {
          title
          message
        }
      }
    }
  }
}
